# North Dakota Century Code from the legislature's own whole-code page https://ndlegis.gov/prod/cencode/ (every section as <div class="section"><h3>number. heading</h3><div class="body">); one fetch. Subsection numbers are drawn by <ol> styles, so they are written back in: ol 1. / alpha a. / pnum (1) / palpha (a).
import re
from html.parser import HTMLParser

URL = 'https://ndlegis.gov/prod/cencode/'
BLOCK = {'p', 'div', 'br', 'tr', 'table', 'h4', 'h5', 'h6', 'ul', 'blockquote', 'pre'}

def letters(n):
    return chr(96 + n) if n <= 26 else chr(96 + n - 26) * 2

def label(kind, n):
    return {'pnum': '(%d)' % n, 'alpha': letters(n) + '.', 'palpha': '(%s)' % letters(n)}.get(kind, '%d.' % n)

class Code(HTMLParser):
    def __init__(self):
        HTMLParser.__init__(self, convert_charrefs=True)
        self.out, self.cur, self.mode, self.depth, self.ols, self.bare = [], None, None, 0, [], False
    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        cls = (a.get('class') or '').split()
        if tag == 'div' and 'section' in cls and (a.get('id') or '').startswith('s-'):
            self.cur = {'id': a['id'][2:], 'h': [], 'b': [], 'pdf': ''}
            self.out.append(self.cur); self.depth, self.mode, self.ols = 1, None, []
            return
        if not self.cur:
            return
        if tag == 'div':
            self.depth += 1
            if 'body' in cls:
                self.mode = 'b'
        elif tag == 'h3':
            self.mode = 'h'
        elif tag == 'a' and 'pdf-link' in cls:
            self.cur['pdf'] = a.get('href') or ''
            self.mode = None
        elif tag == 'button':
            self.mode = None
        if self.mode != 'b':
            return
        if tag == 'ol':
            self.ols.append([next((c for c in cls if c in ('pnum', 'alpha', 'palpha')), '1'), 0])
        elif tag == 'li' and self.ols:
            self.ols[-1][1] += 1
            # "a. (1) Provides ..." — a list that opens its parent's item stays on the parent's line, as printed
            self.cur['b'].append(('' if self.bare else '\n') + label(*self.ols[-1]) + ' ')
            self.bare = True
        elif tag in BLOCK or tag == 'li':
            self.cur['b'].append('\n')
    def handle_endtag(self, tag):
        if not self.cur:
            return
        if tag == 'div':
            self.depth -= 1
            if self.depth == 0:
                self.cur, self.mode = None, None
            elif self.mode == 'b':
                self.mode = None
        elif tag == 'h3' and self.mode == 'h':
            self.mode = None
        elif self.mode == 'b' and tag == 'ol' and self.ols:
            self.ols.pop()
            self.cur['b'].append('\n')
        elif self.mode == 'b' and tag in BLOCK:
            self.cur['b'].append('\n')
    def handle_data(self, d):
        if d.strip():
            self.bare = False
        if self.cur and self.mode:
            self.cur[self.mode].append(d)

def lines(parts):
    return '\n'.join(l for l in (' '.join(x.split()) for x in ''.join(parts).split('\n')) if l)

def from_pdf(sid, pdf):
    """The page gives 50-11.1-02.4 the id of 50-11-02.4; its PDF (t50c11-1.pdf) names the real chapter."""
    m = re.search(r'/t(\d+)(?:-(\d+))?c(\d+)(?:-(\d+))?\.pdf', pdf)
    if not m:
        return sid
    t = str(int(m.group(1))) + ('.' + m.group(2) if m.group(2) else '')
    c = m.group(3) + ('.' + m.group(4) if m.group(4) else '')
    return t + '-' + c + '-' + sid.split('-')[-1]

def sections():
    kind, page = fetch(URL)
    p = Code(); p.feed(page); p.close()
    log('section boxes on the page: %d' % len(p.out))
    seen = set()
    for s in p.out:
        sid = s['id']
        if sid in seen:
            sid = from_pdf(sid, s['pdf'])
            log('duplicate id %s on the page; its PDF says %s' % (s['id'], sid))
        if sid in seen:
            continue
        seen.add(sid)
        head = lines(s['h'])
        if head.startswith(s['id']):
            head = head[len(s['id']):].lstrip('. ').strip()
        text = lines(s['b'])
        if not text:
            continue
        yield {'id': sid, 'heading': head or sid, 'text': text, 'url': s['pdf'] or URL}
